schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/cohort-implementation.json",
  "title": "Cohort Implementation config",
  "type": "object",
  "required": ["settings", "sources", "model", "tests", "chart"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "ident": {"type": "string", "pattern": "^[a-z][a-z0-9_]*$"},
    "utc_col": {"type": "string", "pattern": "^[a-z][a-z0-9_]*_utc$"},
    "rate": {"type": "number", "minimum": 0, "maximum": 1}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "settings": {
      "type": "object",
      "required": ["warehouse_engine", "retention_event", "day_offsets", "week_start", "timezone"],
      "additionalProperties": false,
      "properties": {
        "warehouse_engine": {"type": "string", "enum": ["bigquery", "snowflake", "postgres", "redshift"]},
        "retention_event": {"$ref": "#/definitions/ident"},
        "day_offsets": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "integer", "minimum": 1}},
        "week_start": {"const": "monday"},
        "timezone": {"const": "UTC"}
      }
    },
    "sources": {
      "type": "object",
      "required": ["users_table", "events_table", "user_id_column", "identity_resolved_upstream", "signup_ts_column", "event_ts_column"],
      "additionalProperties": false,
      "properties": {
        "users_table": {"$ref": "#/definitions/ident"},
        "events_table": {"$ref": "#/definitions/ident"},
        "user_id_column": {"const": "user_id"},
        "identity_resolved_upstream": {"const": true},
        "signup_ts_column": {"$ref": "#/definitions/utc_col"},
        "event_ts_column": {"$ref": "#/definitions/utc_col"}
      }
    },
    "model": {
      "type": "object",
      "required": ["name", "materialized", "unique_key", "partition_by", "lookback_days", "cohort_week_expr", "join_condition", "denominator_source", "retention_event_declared_in"],
      "additionalProperties": false,
      "properties": {
        "name": {"$ref": "#/definitions/ident"},
        "materialized": {"const": "incremental"},
        "unique_key": {"type": "array", "minItems": 3, "maxItems": 3, "items": [{"const": "cohort_week"}, {"const": "day_offset"}, {"const": "user_id"}]},
        "partition_by": {"const": "cohort_week"},
        "lookback_days": {"type": "integer", "minimum": 1},
        "cohort_week_expr": {"type": "string", "minLength": 10, "pattern": "(?i)monday"},
        "join_condition": {"const": "event_ts_utc >= signup_ts_utc"},
        "denominator_source": {"const": "users_table"},
        "retention_event_declared_in": {
          "type": "array",
          "minItems": 3,
          "items": {"type": "string", "enum": ["sql", "schema_yml", "settings"]},
          "allOf": [{"contains": {"const": "sql"}}, {"contains": {"const": "schema_yml"}}, {"contains": {"const": "settings"}}]
        }
      }
    },
    "tests": {
      "type": "object",
      "required": ["not_null", "accepted_values"],
      "additionalProperties": false,
      "properties": {
        "not_null": {
          "type": "array",
          "minItems": 3,
          "items": {"$ref": "#/definitions/ident"},
          "allOf": [{"contains": {"const": "cohort_week"}}, {"contains": {"const": "day_offset"}}, {"contains": {"const": "user_id"}}]
        },
        "accepted_values": {
          "type": "object",
          "required": ["column", "values"],
          "additionalProperties": false,
          "properties": {
            "column": {"const": "day_offset"},
            "values": {"type": "array", "minItems": 1, "items": {"type": "integer", "minimum": 1}}
          }
        }
      }
    },
    "chart": {
      "type": "object",
      "required": ["data_cutoff", "x", "series", "metric", "immature_value", "render_immature_as"],
      "additionalProperties": false,
      "properties": {
        "data_cutoff": {"$ref": "#/definitions/date"},
        "x": {"const": "cohort_week"},
        "series": {"const": "day_offset"},
        "metric": {"const": "retained_users / cohort_users"},
        "immature_value": {"type": "null"},
        "render_immature_as": {"const": "blank"}
      }
    },
    "cells": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["cohort_week", "day_offset", "cohort_users", "retained_users", "retention"],
        "additionalProperties": false,
        "properties": {
          "cohort_week": {"$ref": "#/definitions/date"},
          "day_offset": {"type": "integer", "minimum": 1},
          "cohort_users": {"type": "integer", "minimum": 1},
          "retained_users": {"type": ["integer", "null"], "minimum": 0},
          "retention": {"anyOf": [{"$ref": "#/definitions/rate"}, {"type": "null"}]}
        }
      }
    }
  }
}
